def gen(rng):
    def build(r, c, base, step):
        a = [[0] * c for _ in range(r)]
        for i in range(r):
            for j in range(c):
                up = a[i - 1][j] if i else base
                lf = a[i][j - 1] if j else base
                a[i][j] = max(up, lf) + rng.randint(0, step)
        return a
    def fmt(a, t):
        return f'{len(a)} {len(a[0])} {t}\n' + '\n'.join(' '.join(map(str, row)) for row in a)
    def pick(a, present):
        r, c = len(a), len(a[0])
        if present:
            return a[rng.randrange(r)][rng.randrange(c)]
        flat = {v for row in a for v in row}
        t = rng.randint(a[0][0] - 2, a[-1][-1] + 2)
        while t in flat:
            t += 1
        return t
    tests = [fmt([[7]], 7), fmt([[7]], 8), fmt([[1, 2, 3, 4]], 3), fmt([[1], [2], [2], [5]], 2), fmt([[3, 3], [3, 3]], 3)]
    for k in range(10):
        a = build(rng.randint(1, 5), rng.randint(1, 5), rng.randint(-5, 5), rng.randint(0, 3))
        tests.append(fmt(a, pick(a, k % 3 != 2)))
    for r, c, base, step, present in [(300, 300, -1000000, 1500, True), (300, 300, 0, 3, True), (300, 300, 0, 3, False), (300, 300, 0, 0, True), (250, 300, -500, 4, False)]:
        a = build(r, c, base, step)
        tests.append(fmt(a, pick(a, present)))
    return tests
